package set_route

import (
	"github.com/MateusMoutinhoOrg/Agnos/sandbox/api"
)

// NewCommand builds this command's declaration — the whole of what its
// entries.yaml says — and closes CommandHandler over the sandbox as the
// handler behind it. It is called once, by sandbox/internal/cli/new.go, and
// what it returns is one entry of Cli.Commands: the declaration alone, which
// the dispatch copies with api.BindCommand before binding a command line onto
// it.
// Generated by `agnos build` — do not edit by hand; the logic
// lives in handler.go.
func NewCommand(sandbox *api.Sandbox) api.Command {
	command := api.NewCommand()

	command.Name = "set_route"
	command.Identifiers = []string{"set-route"}
	command.Category = "Server System"
	command.Help = "Rewrite the route-level keys of a route.yaml"
	command.LongDescription = "Overwrites method, help, category, long-description, hidden and examples on one route. Empty options leave the current value alone; --example appends."
	command.Examples = []string{"set-route create-user --method POST --example \"curl -X POST localhost:8080/users\""}
	command.Hidden = false

	command.Flags = []api.CommandFlag{
		{
			Id:          "method",
			Type:        "string",
			Required:    false,
			Array:       false,
			Description: "the http method the route answers",
			Examples:    []string{"--method POST"},
			Default:     "",
			HasDefault:  false,
			Identifiers: []string{"--method", "-m"},
		},
		{
			Id:          "help",
			Type:        "string",
			Required:    false,
			Array:       false,
			Description: "one-line description of the route",
			Examples:    []string{"--help \"Create a user\""},
			Default:     "",
			HasDefault:  false,
			Identifiers: []string{"--help"},
		},
		{
			Id:          "category",
			Type:        "string",
			Required:    false,
			Array:       false,
			Description: "the heading the route is listed under in docs/Routes",
			Examples:    []string{"--category Users"},
			Default:     "",
			HasDefault:  false,
			Identifiers: []string{"--category"},
		},
		{
			Id:          "long-description",
			Type:        "string",
			Required:    false,
			Array:       false,
			Description: "the paragraph docs/Routes prints under the route",
			Examples:    []string{"--long-description \"Creates one user under a tenant.\""},
			Default:     "",
			HasDefault:  false,
			Identifiers: []string{"--long-description"},
		},
		{
			Id:          "hidden",
			Type:        "boolean",
			Required:    false,
			Array:       false,
			Description: "drop the route from docs/Routes, still dispatched",
			Examples:    []string{"--hidden"},
			Default:     "",
			HasDefault:  false,
			Identifiers: []string{"--hidden"},
		},
		{
			Id:          "visible",
			Type:        "boolean",
			Required:    false,
			Array:       false,
			Description: "list the route again in docs/Routes",
			Examples:    []string{"--visible"},
			Default:     "",
			HasDefault:  false,
			Identifiers: []string{"--visible"},
		},
		{
			Id:          "path",
			Type:        "string",
			Required:    false,
			Array:       false,
			Description: "the dir holding the project (defaults to the current directory)",
			Examples:    []string{"set-route --path ./my-project"},
			Default:     ".",
			HasDefault:  true,
			Identifiers: []string{"--path"},
		},
		{
			Id:          "quiet",
			Type:        "boolean",
			Required:    false,
			Array:       false,
			Description: "Quiets the cli output",
			Examples:    []string{},
			Default:     "",
			HasDefault:  false,
			Identifiers: []string{"--quiet", "-q"},
		},
		{
			Id:          "example",
			Type:        "string",
			Required:    false,
			Array:       true,
			Description: "an usage example for the route (repeatable)",
			Examples:    []string{"set-route create-user --example \"curl localhost:8080/users\""},
			Default:     "",
			HasDefault:  false,
			Identifiers: []string{"--example"},
		},
		{
			Id:          "priority",
			Type:        "int",
			Required:    false,
			Array:       false,
			Description: "the rung this route runs on when several match one request: lowest first, and a route that writes no status hands the request on",
			Examples:    []string{"set-route logger --priority 0"},
			Default:     "-1",
			HasDefault:  true,
			Identifiers: []string{"--priority"},
		},
	}

	command.Args = []api.CommandArg{
		{
			Id:          "route",
			Type:        "string",
			Required:    true,
			Array:       false,
			Description: "the route to edit (identifier or package name)",
			Examples:    []string{"set-route create-user --help \"Create a user\""},
			Default:     "",
			HasDefault:  false,
		},
	}

	command.Handler = func(bound *api.Command) int {
		return CommandHandler(sandbox, bound)
	}

	return *command
}
